-- Facet landing pages (27. 10. 2026, generated by scripts/gen-fasety-sql.ts from src/data/fasety.ts).
-- Searched category × facet combinations get their own category (H1, title in the searched form, texts); products are
-- assigned nightly by the importer rules generated from the same table (cat_products direct = 2).
INSERT OR IGNORE INTO categories (id, slug, name, parent, description_html, second_html, seo_title) VALUES
(3001, 'krajkove-body', 'Krajkové body', (SELECT id FROM categories WHERE slug = 'damske-body'), '<p>Krajkové body na jednom místě – svůdné body, které poslouží jako erotické prádlo i jako top k sukni nebo pod sako. Ceny porovnáváme u všech ověřených obchodů, se kterými spolupracujeme, a u každého produktu uvidíte, kde je nejlevnější a skladem.</p>', '<h2>Jak vybrat body</h2><ul><li><strong>Velikost</strong> – body by mělo sedět těsně, ale nikde neškrtit; u krajky počítejte s menší pružností.</li><li><strong>Zapínání v rozkroku</strong> usnadní nošení přes den.</li><li><strong>Materiál</strong> – krajka a síťovina působí jemně, latex a koženka odvážněji.</li></ul>', 'Krajkové body: srovnání cen %currentyear% | Eroka'),
