(3011, 'cerne-korzety', 'Černé korzety', (SELECT id FROM categories WHERE slug = 'damske-korzety'), '<p>Černé korzety zeštíhlí pas, zvýrazní postavu a hodí se pod šaty, na rande i do ložnice. Ceny porovnáváme u všech ověřených obchodů, se kterými spolupracujeme, a u každého produktu uvidíte, kde je nejlevnější a skladem.</p>', '<h2>Jak vybrat korzet</h2><ul><li><strong>Obvod pasu</strong> – korzet volte podle pasu, ne podle konfekční velikosti.</li><li><strong>Kostice</strong> – plastové jsou pohodlnější, ocelové víc tvarují.</li><li><strong>Šněrování vzadu</strong> umožní korzet doladit na míru.</li></ul>', 'Černý korzet: srovnání cen %currentyear% | Eroka'),
(3012, 'bile-korzety', 'Bílé korzety', (SELECT id FROM categories WHERE slug = 'damske-korzety'), '<p>Bílé korzety zeštíhlí pas, zvýrazní postavu a hodí se pod šaty, na rande i do ložnice. Ceny porovnáváme u všech ověřených obchodů, se kterými spolupracujeme, a u každého produktu uvidíte, kde je nejlevnější a skladem.</p>', '<h2>Jak vybrat korzet</h2><ul><li><strong>Obvod pasu</strong> – korzet volte podle pasu, ne podle konfekční velikosti.</li><li><strong>Kostice</strong> – plastové jsou pohodlnější, ocelové víc tvarují.</li><li><strong>Šněrování vzadu</strong> umožní korzet doladit na míru.</li></ul>', 'Bílý korzet: srovnání cen %currentyear% | Eroka'),
