(3021, 'bile-puncochy', 'Bílé punčochy', (SELECT id FROM categories WHERE slug = 'damske-puncochy'), '<p>Bílé punčochy doplní erotické prádlo, podvazkový pás i večerní šaty. Ceny porovnáváme u všech ověřených obchodů, se kterými spolupracujeme, a u každého produktu uvidíte, kde je nejlevnější a skladem.</p>', '<h2>Na co se dívat</h2><ul><li><strong>Denier (DEN)</strong> – nižší číslo znamená jemnější a průsvitnější punčochy.</li><li><strong>Samodržící lem</strong>, nebo podvazky – samodržící drží samy, podvazkové potřebují pás.</li><li><strong>Velikost</strong> – řiďte se výškou a hmotností v tabulce prodejce.</li></ul>', 'Bílé punčochy: srovnání cen %currentyear% | Eroka'),
(3022, 'cervene-puncochy', 'Červené punčochy', (SELECT id FROM categories WHERE slug = 'damske-puncochy'), '<p>Červené punčochy doplní erotické prádlo, podvazkový pás i večerní šaty. Ceny porovnáváme u všech ověřených obchodů, se kterými spolupracujeme, a u každého produktu uvidíte, kde je nejlevnější a skladem.</p>', '<h2>Na co se dívat</h2><ul><li><strong>Denier (DEN)</strong> – nižší číslo znamená jemnější a průsvitnější punčochy.</li><li><strong>Samodržící lem</strong>, nebo podvazky – samodržící drží samy, podvazkové potřebují pás.</li><li><strong>Velikost</strong> – řiďte se výškou a hmotností v tabulce prodejce.</li></ul>', 'Červené punčochy: srovnání cen %currentyear% | Eroka'),
(3023, 'cerne-puncochy', 'Černé punčochy', (SELECT id FROM categories WHERE slug = 'damske-puncochy'), '<p>Černé punčochy doplní erotické prádlo, podvazkový pás i večerní šaty. Ceny porovnáváme u všech ověřených obchodů, se kterými spolupracujeme, a u každého produktu uvidíte, kde je nejlevnější a skladem.</p>', '<h2>Na co se dívat</h2><ul><li><strong>Denier (DEN)</strong> – nižší číslo znamená jemnější a průsvitnější punčochy.</li><li><strong>Samodržící lem</strong>, nebo podvazky – samodržící drží samy, podvazkové potřebují pás.</li><li><strong>Velikost</strong> – řiďte se výškou a hmotností v tabulce prodejce.</li></ul>', 'Černé punčochy: srovnání cen %currentyear% | Eroka'),
(3024, 'ruzove-puncochy', 'Růžové punčochy', (SELECT id FROM categories WHERE slug = 'damske-puncochy'), '<p>Růžové punčochy doplní erotické prádlo, podvazkový pás i večerní šaty. Ceny porovnáváme u všech ověřených obchodů, se kterými spolupracujeme, a u každého produktu uvidíte, kde je nejlevnější a skladem.</p>', '<h2>Na co se dívat</h2><ul><li><strong>Denier (DEN)</strong> – nižší číslo znamená jemnější a průsvitnější punčochy.</li><li><strong>Samodržící lem</strong>, nebo podvazky – samodržící drží samy, podvazkové potřebují pás.</li><li><strong>Velikost</strong> – řiďte se výškou a hmotností v tabulce prodejce.</li></ul>', 'Růžové punčochy: srovnání cen %currentyear% | Eroka'),
(3031, 'krajkove-eroticke-pradlo', 'Krajkové erotické prádlo', (SELECT id FROM categories WHERE slug = 'eroticke-pradlo'), '<p>Krajkové erotické prádlo: soupravy, podprsenky, kalhotky, košilky i body na jednom místě. Ceny porovnáváme u všech ověřených obchodů, se kterými spolupracujeme, a u každého produktu uvidíte, kde je nejlevnější a skladem.</p>', '<h2>Tipy k výběru</h2><ul><li>Krajka je jemná a hodí se i na běžné nošení, latex a lak jsou spíš na hrátky.</li><li>U souprav zkontrolujte, zda se velikost podprsenky a kalhotek dá kombinovat.</li></ul>', 'Krajkové prádlo: srovnání cen %currentyear% | Eroka'),
(3032, 'latexove-eroticke-pradlo', 'Latexové erotické prádlo', (SELECT id FROM categories WHERE slug = 'eroticke-pradlo'), '<p>Latexové erotické prádlo: soupravy, podprsenky, kalhotky, košilky i body na jednom místě. Ceny porovnáváme u všech ověřených obchodů, se kterými spolupracujeme, a u každého produktu uvidíte, kde je nejlevnější a skladem.</p>', '<h2>Tipy k výběru</h2><ul><li>Krajka je jemná a hodí se i na běžné nošení, latex a lak jsou spíš na hrátky.</li><li>U souprav zkontrolujte, zda se velikost podprsenky a kalhotek dá kombinovat.</li></ul>', 'Latexové prádlo: srovnání cen %currentyear% | Eroka'),
(3041, 'ruzova-pouta', 'Růžová pouta', (SELECT id FROM categories WHERE slug = 'eroticka-pouta'), '<p>Růžová pouta pro začátečníky i pokročilé – na zápěstí i kotníky, se zapínáním na suchý zip, přezku nebo klíček. Ceny porovnáváme u všech ověřených obchodů, se kterými spolupracujeme, a u každého produktu uvidíte, kde je nejlevnější a skladem.</p>', '<h2>Bezpečně s pouty</h2><ul><li>Pouta s polstrováním nebo z měkké kůže neodírají ani při delším nošení.</li><li>Kovová pouta mějte vždy s klíčkem po ruce, ideálně s pojistkou proti utahování.</li><li>Domluvte si bezpečné slovo.</li></ul>', 'Růžová pouta: srovnání cen %currentyear% | Eroka'),
(3042, 'kozena-eroticka-pouta', 'Kožená pouta', (SELECT id FROM categories WHERE slug = 'eroticka-pouta'), '<p>Kožená pouta pro začátečníky i pokročilé – na zápěstí i kotníky, se zapínáním na suchý zip, přezku nebo klíček. Ceny porovnáváme u všech ověřených obchodů, se kterými spolupracujeme, a u každého produktu uvidíte, kde je nejlevnější a skladem.</p>', '<h2>Bezpečně s pouty</h2><ul><li>Pouta s polstrováním nebo z měkké kůže neodírají ani při delším nošení.</li><li>Kovová pouta mějte vždy s klíčkem po ruce, ideálně s pojistkou proti utahování.</li><li>Domluvte si bezpečné slovo.</li></ul>', 'Kožená pouta: srovnání cen %currentyear% | Eroka'),
(3043, 'kovova-eroticka-pouta', 'Kovová pouta', (SELECT id FROM categories WHERE slug = 'eroticka-pouta'), '<p>Kovová pouta pro začátečníky i pokročilé – na zápěstí i kotníky, se zapínáním na suchý zip, přezku nebo klíček. Ceny porovnáváme u všech ověřených obchodů, se kterými spolupracujeme, a u každého produktu uvidíte, kde je nejlevnější a skladem.</p>', '<h2>Bezpečně s pouty</h2><ul><li>Pouta s polstrováním nebo z měkké kůže neodírají ani při delším nošení.</li><li>Kovová pouta mějte vždy s klíčkem po ruce, ideálně s pojistkou proti utahování.</li><li>Domluvte si bezpečné slovo.</li></ul>', 'Kovová pouta: srovnání cen %currentyear% | Eroka'),
(3051, 'kozene-bice', 'Kožené biče a důtky', (SELECT id FROM categories WHERE slug = 'dutky-biciky-a-placacky'), '<p>Kožené biče a důtky pro jemné i ostřejší BDSM hrátky – od měkkých důtek po pevné bičíky. Ceny porovnáváme u všech ověřených obchodů, se kterými spolupracujeme, a u každého produktu uvidíte, kde je nejlevnější a skladem.</p>', '<h2>Jak začít</h2><ul><li>Na začátek jsou vhodnější důtky s širokými měkkými pruhy, které spíš hladí.</li><li>Pravá kůže je odolná a příjemná, po použití ji ošetřete.</li><li>Míří se na hýždě a stehna, nikdy ne na páteř a ledviny.</li></ul>', 'Kožený bič: srovnání cen %currentyear% | Eroka'),
(3061, 'latexove-masky', 'Latexové masky', (SELECT id FROM categories WHERE slug = 'bdsm-masky'), '<p>Latexové masky na fetiš a BDSM hry – kukly přes celou hlavu, masky na oči i škrabošky. Ceny porovnáváme u všech ověřených obchodů, se kterými spolupracujeme, a u každého produktu uvidíte, kde je nejlevnější a skladem.</p>', '<h2>Na co si dát pozor</h2><ul><li>Maska musí mít dostatečné otvory pro dýchání.</li><li>Latex natírejte silikonovým přípravkem, lépe se obléká a déle vydrží.</li><li>Kožené masky ošetřujte prostředkem na kůži.</li></ul>', 'Latexová maska: srovnání cen %currentyear% | Eroka'),
(3062, 'kozene-masky', 'Kožené masky', (SELECT id FROM categories WHERE slug = 'bdsm-masky'), '<p>Kožené masky na fetiš a BDSM hry – kukly přes celou hlavu, masky na oči i škrabošky. Ceny porovnáváme u všech ověřených obchodů, se kterými spolupracujeme, a u každého produktu uvidíte, kde je nejlevnější a skladem.</p>', '<h2>Na co si dát pozor</h2><ul><li>Maska musí mít dostatečné otvory pro dýchání.</li><li>Latex natírejte silikonovým přípravkem, lépe se obléká a déle vydrží.</li><li>Kožené masky ošetřujte prostředkem na kůži.</li></ul>', 'Kožená maska: srovnání cen %currentyear% | Eroka'),
(3071, 'kondomy-pepino', 'Kondomy Pepino', (SELECT id FROM categories WHERE slug = 'kondomy'), '<p>Kondomy Pepino – všechny druhy a balení, které nabízejí české e-shopy, od klasických po tenké a ochucené. Ceny porovnáváme u všech ověřených obchodů, se kterými spolupracujeme, a u každého produktu uvidíte, kde je nejlevnější a skladem.</p>', '<h2>Jak vybrat kondom</h2><ul><li><strong>Velikost</strong> – rozhoduje šířka (nominální šíře), ne délka.</li><li><strong>Materiál</strong> – při alergii na latex volte bezlatexové kondomy.</li><li>Kondomy kombinujte jen s lubrikantem na vodní nebo silikonové bázi, olej latex poškozuje.</li></ul>', 'Pepino kondomy: srovnání cen %currentyear% | Eroka'),
(3074, 'kondomy-my-size', 'Kondomy My Size', (SELECT id FROM categories WHERE slug = 'kondomy'), '<p>Kondomy My Size – všechny druhy a balení, které nabízejí české e-shopy, od klasických po tenké a ochucené. Ceny porovnáváme u všech ověřených obchodů, se kterými spolupracujeme, a u každého produktu uvidíte, kde je nejlevnější a skladem.</p>', '<h2>Jak vybrat kondom</h2><ul><li><strong>Velikost</strong> – rozhoduje šířka (nominální šíře), ne délka.</li><li><strong>Materiál</strong> – při alergii na latex volte bezlatexové kondomy.</li><li>Kondomy kombinujte jen s lubrikantem na vodní nebo silikonové bázi, olej latex poškozuje.</li></ul>', 'My size kondomy: srovnání cen %currentyear% | Eroka'),
(3075, 'svitici-kondomy', 'Svítící kondomy', (SELECT id FROM categories WHERE slug = 'kondomy'), '<p>Svítící kondomy po nasvícení ve tmě jemně září – zábavné zpestření, které chrání stejně jako běžný kondom. Ceny porovnáváme u všech ověřených obchodů, se kterými spolupracujeme, a u každého produktu uvidíte, kde je nejlevnější a skladem.</p>', '<h2>Jak vybrat kondom</h2><ul><li><strong>Velikost</strong> – rozhoduje šířka (nominální šíře), ne délka.</li><li><strong>Materiál</strong> – při alergii na latex volte bezlatexové kondomy.</li><li>Kondomy kombinujte jen s lubrikantem na vodní nebo silikonové bázi, olej latex poškozuje.</li></ul>', 'Svítící kondomy: srovnání cen %currentyear% | Eroka'),
(3082, 'lubrikacni-gely-system-jo', 'Lubrikační gely System JO', (SELECT id FROM categories WHERE slug = 'lubrikacni-gely-a-oleje'), '<p>Lubrikační gely System JO – gely na vodní i silikonové bázi, hřejivé i s příchutí. Ceny porovnáváme u všech ověřených obchodů, se kterými spolupracujeme, a u každého produktu uvidíte, kde je nejlevnější a skladem.</p>', '<h2>Jaký lubrikant zvolit</h2><ul><li><strong>Na vodní bázi</strong> – univerzální, ke všem pomůckám i kondomům.</li><li><strong>Silikonový</strong> – klouže déle a funguje i ve vodě, nehodí se k silikonovým hračkám.</li><li><strong>Hřejivý nebo s příchutí</strong> – na zpestření a orální hrátky.</li></ul>', 'System jo lubrikant: srovnání cen %currentyear% | Eroka'),
(3092, 'vibratory-pro-muze', 'Vibrátory pro muže', (SELECT id FROM categories WHERE slug = 'vibratory'), '<p>Vibrátory pro muže: stimulátory prostaty, vibrační kroužky, masturbátory s vibracemi a další hračky pro pány. Ceny porovnáváme u všech ověřených obchodů, se kterými spolupracujeme, a u každého produktu uvidíte, kde je nejlevnější a skladem.</p>', '<h2>Podle čeho vybírat</h2><ul><li>Tělově nezávadný silikon je příjemný a snadno se čistí.</li><li>Nabíjení přes USB vyjde levněji než baterie.</li><li>Voděodolný vibrátor můžete používat i ve sprše.</li></ul>', 'Vibrátory pro muže: srovnání cen %currentyear% | Eroka'),
(3101, 'kovove-analni-koliky', 'Kovové anální kolíky', (SELECT id FROM categories WHERE slug = 'analni-koliky'), '<p>Kovové anální kolíky – hladké, těžké a snadno se čistí, mnohé se dají nahřát nebo zchladit. Ceny porovnáváme u všech ověřených obchodů, se kterými spolupracujeme, a u každého produktu uvidíte, kde je nejlevnější a skladem.</p>', '<h2>Kovové kolíky</h2><ul><li>Nerez je hygienická a snadno se dezinfikuje.</li><li>Kov drží teplotu – kolík můžete nahřát v teplé vodě nebo zchladit.</li><li>Vždy používejte dostatek lubrikantu a kolík s rozšířenou základnou.</li></ul>', 'Kovový anální kolík: srovnání cen %currentyear% | Eroka'),
(3111, 'vibracni-venusiny-kulicky', 'Vibrační venušiny kuličky', (SELECT id FROM categories WHERE slug = 'venusiny-kulicky'), '<p>Vibrační venušiny kuličky posilují pánevní dno a vibrace přidávají příjemnou stimulaci během nošení. Ceny porovnáváme u všech ověřených obchodů, se kterými spolupracujeme, a u každého produktu uvidíte, kde je nejlevnější a skladem.</p>', '<h2>Jak na vibrační kuličky</h2><ul><li>Začněte s lehčí sadou a noste ji zpočátku jen několik minut denně.</li><li>Modely s aplikací umí řídit vibrace i na dálku.</li><li>Po použití kuličky omyjte vodou a mýdlem.</li></ul>', 'Vibrační venušiny kuličky: srovnání cen %currentyear% | Eroka');

